 internal static int Run(BlueprintsCache cache){caster=new Psychic070Tests.Caster(cache).Unit;target=new Psychic070Tests.Caster(cache).Unit;Set(target.Descriptor,"<Blueprint>k__BackingField",new BlueprintUnit {IsCheater=false});facts=new EntityFactsManager(target);Set(target,"Facts",facts);var bc=new BuffCollection();bc.Initialize(facts);Set(target,"<Buffs>k__BackingField",bc);var h=new Harmony("CotW028.Independent");h.Patch(AccessTools.Method(typeof(Buff),"Remove"),prefix:new HarmonyMethod(typeof(Psychic028Tests),nameof(Remove)));
