 static bool UnitBlueprint(ref BlueprintUnit __result){__result=new BlueprintUnit {IsCheater=false};return false;}
 static bool Remove(){removed++;return false;}
 static void Seeds(BlueprintsCache c){var host=Asset<BlueprintBuff>(c,"FireSeedsBuff");var resource=Asset<BlueprintAbilityResource>(c,"FireSeedsResource");var root=Asset<BlueprintAbility>(c,"FireSeeds");var menu=Asset<BlueprintAbility>(c,"FireSeedsThrow");Check(resource.GetMaxAmount(target.Descriptor)==20,"resource hard ceiling");Check(root.GetComponents<SpellListComponent>().Single().SpellLevel==6,"Druid6");
 foreach(int cl in new[]{1,6,12,20,30}){Clear();var b=Fact(host,cl);Check(b.Components.Count==host.ComponentsArray.Length,"all differently named components initialized");var dict=b.Components.ToDictionary(x=>x.SourceBlueprintComponentName);Check(dict.Count==12,"save keys retain all resource/grant/inherited-context components");var rt=b.Components.Single(x=>x.SourceBlueprintComponent is PsychicSeedPool);using(rt.RequestEventContext()){
  AccessTools.Method(typeof(PsychicSeedPool),"OnActivate").Invoke(rt.SourceBlueprintComponent,null);Check(target.Descriptor.Resources.GetResourceAmount(resource)==Math.Min(20,cl),"caster level initializes recipient pool");
  var a=menu.GetComponent<AbilityVariants>().Variants.First();var logic=a.GetComponent<AbilityResourceLogic>();var data=new AbilityData(a,target.Descriptor);logic.Spend(data);Check(target.Descriptor.Resources.GetResourceAmount(resource)==Math.Min(20,cl)-1,"native ability resource spend");
  target.Descriptor.Resources.Spend(resource,target.Descriptor.Resources.GetResourceAmount(resource));int before=removed;((PsychicSeedPool)rt.SourceBlueprintComponent).OnNewRound();Check(removed==before+1,"exhausted pool removes host");AccessTools.Method(typeof(PsychicSeedPool),"OnDeactivate").Invoke(rt.SourceBlueprintComponent,null);Check(!target.Descriptor.Resources.ContainsResource(resource),"deactivation removes resource");
 }}
 var choices=menu.GetComponent<AbilityVariants>().Variants;Check(choices.Length==10,"one menu ten costs");for(int i=0;i<10;i++){var a=choices[i];Check(a.Parent==menu&&a.Type==AbilityType.SpellLike&&!a.SpellResistance,"temporary child and no SR");Check(a.GetComponent<AbilityResourceLogic>().Amount==i+1,"1..10 native resource cost");Check(a.GetComponent<AbilityEffectMiss>().UseTargetSelector,"miss uses splash selector");Check(a.GetComponent<AbilityDeliverProjectile>()!=null&&a.GetComponent<AbilityTargetsAround>()!=null,"native projectile and splash");var miss=a.GetComponent<AbilityEffectMiss>().MissAction.Actions.OfType<ContextActionDealDamage>().Single();Check(miss.Value.BonusValue.Value==i+1&&miss.Value.DiceCountValue.Value==0,"miss deals splash only");}
 }
 static void Hex(BlueprintsCache c){Clear();var bp=Asset<BlueprintBuff>(c,"HexVulnerabilityBuff");var b=Fact(bp);var type=typeof(PsychicSeedPool).Assembly.GetType("CallOfTheWild.Wrath.Prototype.PsychicHexVulnerability");var pairs=(string[][])AccessTools.Field(type,"Pairs").GetValue(null);var bypass=AccessTools.Method(type,"Bypass");var patch=typeof(PsychicSeedPool).Assembly.GetType("CallOfTheWild.Wrath.Prototype.PsychicHexCooldownPatch");var h=new Harmony("CotW028.HexActualHook");h.CreateClassProcessor(patch).Patch();
 try{foreach(var pair in pairs){var cd=new BlueprintBuff {AssetGuid=BlueprintGuid.Parse(pair[1]),name="AuditedNativeCooldown"};if(c.Load(cd.AssetGuid)==null)c.AddCachedBlueprint(cd.AssetGuid,cd);else cd=(BlueprintBuff)c.Load(cd.AssetGuid);var check=new AbilityTargetHasFact {Inverted=true};Set(check,"m_CheckedFacts",new[]{BlueprintReferenceBase.CreateTyped<BlueprintUnitFactReference>(cd)});var a=new BlueprintAbility {AssetGuid=BlueprintGuid.Parse(pair[0]),ComponentsArray=new BlueprintComponent[]{check}};a.OnEnable();var cooldown=Fact(cd);Check(check.IsTargetRestrictionPassed(caster,new TargetWrapper(target)),"installed native postfix bypasses same caster cooldown");Check(!check.IsTargetRestrictionPassed(target,new TargetWrapper(target)),"different caster remains blocked");Set(b,"<IsTurnedOn>k__BackingField",false);Check(!check.IsTargetRestrictionPassed(caster,new TargetWrapper(target)),"expired vulnerability does not bypass");Set(b,"<IsTurnedOn>k__BackingField",true);check.Inverted=false;Check(!(bool)bypass.Invoke(null,new object[]{check,caster,new TargetWrapper(target)}),"positive requirement preserved");check.Inverted=true;Set(check,"m_CheckedFacts",new[]{BlueprintReferenceBase.CreateTyped<BlueprintUnitFactReference>(cd),BlueprintReferenceBase.CreateTyped<BlueprintUnitFactReference>(bp)});Check(!(bool)bypass.Invoke(null,new object[]{check,caster,new TargetWrapper(target)}),"mixed requirements preserved");facts.List.Remove(cooldown);AccessTools.Method(Get(facts,"m_Cache").GetType(),"Clear").Invoke(Get(facts,"m_Cache"),null);}
 }finally{h.UnpatchAll(h.Id);}
 var spell=Asset<BlueprintAbility>(c,"HexVulnerability");Check(spell.SpellResistance&&spell.GetComponents<SpellListComponent>().Count()==2,"Witch/Shaman spell with SR");var actions=spell.GetComponent<AbilityEffectRunAction>().Actions.Actions;Check(actions[0] is ContextActionSavingThrow&&actions[1] is ContextActionApplyBuff,"repeat resistance applied after save on both outcomes");var applied=(ContextActionApplyBuff)actions[1];
 var cast=new MechanicsContext(caster,target.Descriptor,spell,null,new TargetWrapper(target));cast.SetParams(new AbilityParams {DC=24,CasterLevel=12,SpellLevel=1});Clear();for(int stacks=1;stacks<=4;stacks++){Fact(applied.Buff);var save=new RuleSavingThrow(target,SavingThrowType.Will,24){Reason=new RuleReason(cast)};foreach(var fact in facts.List.OfType<Buff>())fact.CallComponents<PsychicHexResistance>(x=>x.OnEventAboutToTrigger(save));Check(save.AllBonuses.Sum(x=>x.Value)==4*stacks,"native cumulative +4 per previous casting");}var other=new RuleSavingThrow(target,SavingThrowType.Will,24);foreach(var fact in facts.List.OfType<Buff>())fact.CallComponents<PsychicHexResistance>(x=>x.OnEventAboutToTrigger(other));Check(other.AllBonuses.Sum(x=>x.Value)==0,"resistance never applies to unrelated saves");Check(applied.IsNotDispelable&&applied.DurationValue.Rate==DurationRate.Days&&applied.DurationValue.BonusValue.Value==1,"24-hour non-dispellable resistance");
 }
 static void Shuriken(BlueprintsCache c){var host=Asset<BlueprintBuff>(c,"FieryShurikenBuff");var resource=Asset<BlueprintAbilityResource>(c,"FieryShurikenResource");var all=Asset<BlueprintAbility>(c,"FieryShurikenAll");var one=Asset<BlueprintAbility>(c,"FieryShurikenOne");var menu=Asset<BlueprintAbility>(c,"FieryShurikenLaunch");
 for(int cl=1;cl<=30;cl++){Clear();var b=Fact(host,cl);var rt=b.Components.Single(x=>x.SourceBlueprintComponent is PsychicSeedPool);using(rt.RequestEventContext()){AccessTools.Method(typeof(PsychicSeedPool),"OnActivate").Invoke(rt.SourceBlueprintComponent,null);int expected=cl<3?2:Math.Min(8,2+(cl-3)/2);Check(target.Descriptor.Resources.GetResourceAmount(resource)==expected-1,"one initial launch leaves CL-scaled shuriken");var rank=all.GetComponent<ContextRankConfig>();Check(rank.GetValue(b.Context)==expected,"native initial-all rank at CL "+cl);AccessTools.Method(typeof(PsychicSeedPool),"OnDeactivate").Invoke(rt.SourceBlueprintComponent,null);Check(!target.Descriptor.Resources.ContainsResource(resource),"shuriken pool cleaned");}}
 Check(one.GetComponent<AbilityExecuteActionOnCast>()!=null,"retain pool on cast even when initial projectile misses");Check(all.GetComponent<AbilityExecuteActionOnCast>().Actions.Actions.Single() is ContextActionRemoveBuff,"all-projectile recast clears old retained pool");var variants=menu.GetComponent<AbilityVariants>().Variants;for(int i=0;i<7;i++){var a=variants[i];Check(a.GetComponent<AbilityDeliverProjectile>().Projectiles.Length==i+1,"per-projectile delivery count");Check(a.GetComponent<AbilityResourceLogic>().Amount==i+1,"per-projectile spend count");Check(a.Type==AbilityType.Supernatural&&a.SpellResistance,"retained launch no casting AoO, keeps SR");Check(a.ActionType==(i==0?Kingmaker.UnitLogic.Commands.Base.UnitCommand.CommandType.Swift:Kingmaker.UnitLogic.Commands.Base.UnitCommand.CommandType.Standard),"swift single / standard volley");}
 }
 static void VoidOrb(BlueprintsCache c){Clear();var host=Asset<BlueprintBuff>(c,"OrbOfTheVoidController");var area=Asset<BlueprintAbilityAreaEffect>(c,"OrbOfTheVoidArea");var spell=Asset<BlueprintAbility>(c,"OrbOfTheVoid");var move=Asset<BlueprintAbility>(c,"OrbOfTheVoidMove");Check(spell.GetComponents<SpellListComponent>().Count()==2&&spell.GetComponents<SpellListComponent>().All(x=>x.SpellLevel==8),"cleric/wizard8 root");Check(move.ActionType==Kingmaker.UnitLogic.Commands.Base.UnitCommand.CommandType.Move&&move.Range==AbilityRange.Close,"close-range move action");Check(host.ComponentsArray.All(x=>!string.IsNullOrEmpty(x.name)),"runtime/save names");Check(area.GetComponent<UniqueAreaEffect>().Feature==host&&area.Fx!=null,"source-owned area FX");Check(spell.GetComponent<Kingmaker.UnitLogic.Abilities.Components.Base.AbilitySpawnFx>()==null,"no duplicate unowned loop FX");var run=area.GetComponent<AbilityAreaEffectRunAction>();var pulse=(PsychicOrbPulse)run.UnitEnter.Actions.Single();Check(pulse.Controller.Get()==host&&run.Round.Actions.Single() is PsychicOrbPulse,"entry/round shared cooldown pipeline");var cond=(Kingmaker.Designers.EventConditionActionSystem.Actions.Conditional)pulse.Effects.Actions.Single();var apply=(ContextActionApplyBuff)cond.IfTrue.Actions.Single();Check(apply.DurationValue.Rate==DurationRate.Hours&&apply.DurationValue.BonusValue.Value==1&&apply.NotLinkToAreaEffect,"undead THP survives area exit for one hour");var hp=apply.Buff;Check(hp.Stacking==StackingType.Replace,"reapplication cannot stack THP");var roll=hp.GetComponent<ContextCalculateSharedValue>();Check(roll.Value.DiceCountValue.Value==2&&roll.Value.DiceType==Kingmaker.RuleSystem.DiceType.D4&&roll.Modifier==5,"2d4 times5, not10d4");var save=(ContextActionSavingThrow)cond.IfFalse.Actions.Single();Check(save.Type==SavingThrowType.Fortitude,"living Fortitude");var saved=(ContextActionConditionalSaved)save.Actions.Actions.Single();Check(saved.Succeed.Actions.Length==0,"successful save prevents drain");var drain=(ContextActionDealDamage)saved.Failed.Actions.Single();Check(Get(drain,"m_Type").ToString()=="EnergyDrain"&&drain.Value.BonusValue.Value==1&&drain.EnergyDrainType==EnergyDrainType.Temporary,"native single temporary negative level");Check(drain.Duration.Rate==DurationRate.Days&&drain.Duration.BonusValue.Value==1,"negative level24hours");Check(spell.MaterialComponent.Count==2,"two diamond dust");
 }

